def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    multiple = (remaining // item) * item
    diff = np.abs(remaining - multiple)
    return np.where(remaining >= 0, -diff, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_remaining = 0.2 * bins
    diff = np.abs(remaining - target_remaining)
    return np.where(remaining >= 0, -diff, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining % item, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, np.floor(remaining / item), -np.inf)
